import hashlib


def _score(script_id, grader):
    return hashlib.sha256(f"{grader}|{script_id}".encode("utf-8")).digest()


def assign(script_ids, graders):
    others = [g for g in graders if g != "Nadia"]
    out = {}
    for s in script_ids:
        if s.startswith("CSE4111") and "Nadia" in graders:
            out[s] = "Nadia"
        else:
            out[s] = max(others, key=lambda g: _score(s, g))
    return out
